import { Host, h, Component, Prop, type ComponentInterface } from '@stencil/core';
import { useIcon } from '../runtime';

@Component({
  tag: 'ks-icon-circle',
  styleUrls: ['../styles/index.css'],
  shadow: true,
})
export class KsIconCircle implements ComponentInterface {
  ['ks-icon-name']: string = 'ks-icon-circle';

  @Prop() size: string | number = 16;
  @Prop() color: string = 'currentColor';
  /**
   * @deprecated
   */
  @Prop() strokeWidth: string | number;
  /**
   * @deprecated
   */
  @Prop() absoluteStrokeWidth: boolean = false;

  render() {
    const icon = useIcon({ size: this.size, color: this.color });

    return (
      <Host class="ks-icon" ks-icon>
        <svg width={icon.width} height={icon.height} viewBox="0 0 48 48" fill="none" xmlns="http://www.w3.org/2000/svg">
          <path
            d="M45.0001 23.9999C45.0001 12.4019 35.5981 2.99986 24.0001 2.99986C12.4022 2.99986 3.00014 12.4019 3.00014 23.9999C3.00014 35.5978 12.4022 44.9999 24.0001 44.9999C35.5981 44.9999 45.0001 35.5978 45.0001 23.9999Z"
            stroke={icon.color}
            stroke-width={icon.strokeWidth}
            stroke-linejoin="round"
          ></path>
        </svg>
      </Host>
    );
  }
}
